export function InteractiveFeature() {
  const containerRef = useRef<HTMLDivElement>(null);

  // Spring configurations for smooth movement
  const springConfig = { damping: 25, stiffness: 120 };

  // Motion values for the interactive spotlight
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  // Smoothed versions of mouse position for transforms
  const smoothX = useSpring(mouseX, springConfig);
  const smoothY = useSpring(mouseY, springConfig);

  // Transform mouse position to rotation and movement values
  const rotateX = useTransform(smoothY, [-300, 300], [15, -15]); 
  const rotateY = useTransform(smoothX, [-300, 300], [-15, 15]);
  const lightX = useTransform(smoothX, (x) => `${x}px`);
  const lightY = useTransform(smoothY, (y) => `${y}px`);

  const handleMouseMove = (event: React.MouseEvent) => {
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;

    // Calculate distance from center
    mouseX.set(event.clientX - centerX);
    mouseY.set(event.clientY - centerY);
  };

  const handleMouseLeave = () => {
    mouseX.set(0);
    mouseY.set(0);
  };

